  on_linux do
    on_arm do
      url "https://github.com/m18h/kanea/releases/download/v0.20.0/kanea_0.20.0_linux_arm64.tar.gz"
      sha256 "a831e7d86de3d9278ca40edccb1603d90e79d34806d09d999a870a0fe31cbbfa"
